BEGIN TRANSACTION READ ONLY;
DO $$ BEGIN IF current_database()<>'duta_rantau_staging' THEN RAISE EXCEPTION 'wrong database'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN ('duta_app','duta_system') AND (rolsuper OR rolbypassrls OR rolcreaterole OR rolcreatedb OR rolreplication)) THEN RAISE EXCEPTION 'unsafe runtime role'; END IF; IF (SELECT count(*) FROM pg_roles WHERE rolname IN ('duta_app','duta_system') AND rolcanlogin)<>2 THEN RAISE EXCEPTION 'runtime roles missing'; END IF; END $$;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname IN ('public','drizzle') AND r.rolname IN ('duta_app','duta_system')) THEN RAISE EXCEPTION 'runtime role owns object'; END IF; END $$;
DO $$ BEGIN IF to_regprocedure('public.current_app_user_id()') IS NULL OR to_regprocedure('public.current_app_has_role(user_role[])') IS NULL OR to_regprocedure('public.current_app_has_org_role(uuid,organization_role[])') IS NULL THEN RAISE EXCEPTION 'identity helpers missing'; END IF; END $$;
DO $$ BEGIN IF public.current_app_user_id() IS NOT NULL THEN RAISE EXCEPTION 'missing identity did not return null'; END IF; END $$;
DO $$ BEGIN IF (SELECT count(*) FROM pg_tables WHERE schemaname='public' AND rowsecurity)<>36 THEN RAISE EXCEPTION 'expected 36 RLS tables'; END IF; IF (SELECT count(*) FROM pg_policies WHERE schemaname='public')<>85 THEN RAISE EXCEPTION 'expected 85 policies'; END IF; END $$;
DO $$ BEGIN IF has_schema_privilege('duta_app','public','CREATE') OR has_schema_privilege('duta_system','public','CREATE') THEN RAISE EXCEPTION 'runtime schema CREATE privilege'; END IF; IF has_table_privilege('duta_app','public.jobs','INSERT') OR has_table_privilege('duta_app','public.jobs','UPDATE') OR has_table_privilege('duta_app','public.jobs','DELETE') THEN RAISE EXCEPTION 'job mutation privilege leaked'; END IF; IF has_table_privilege('duta_app','public.payments','INSERT') OR has_table_privilege('duta_app','public.audit_logs','DELETE') OR has_table_privilege('duta_app','public.sessions','SELECT') THEN RAISE EXCEPTION 'sensitive privilege leaked'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM drizzle.__drizzle_migrations WHERE created_at=1787036103000) THEN RAISE EXCEPTION 'migration 0004 ledger entry missing'; END IF; IF NOT EXISTS(SELECT 1 FROM drizzle.__drizzle_migrations WHERE created_at=1787968300537) THEN RAISE EXCEPTION 'migration 0005 ledger entry missing'; END IF; IF NOT EXISTS(SELECT 1 FROM drizzle.__drizzle_migrations WHERE created_at=1787968301000) THEN RAISE EXCEPTION 'migration 0006 ledger entry missing'; END IF; IF NOT EXISTS(SELECT 1 FROM drizzle.__drizzle_migrations WHERE created_at=1788189382794) THEN RAISE EXCEPTION 'migration 0007 ledger entry missing'; END IF; IF NOT EXISTS(SELECT 1 FROM drizzle.__drizzle_migrations WHERE created_at=1788190000000) THEN RAISE EXCEPTION 'migration 0008 ledger entry missing'; END IF; IF NOT EXISTS(SELECT 1 FROM drizzle.__drizzle_migrations WHERE created_at=1788191000000) THEN RAISE EXCEPTION 'migration 0009 ledger entry missing'; END IF; END $$;
DO $$ BEGIN IF (SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND t.tgname LIKE 'protect_%')<>10 THEN RAISE EXCEPTION 'protection trigger count mismatch'; END IF; END $$;
SELECT 'PHASE3_LOCAL_VERIFICATION_PASS' AS result,(SELECT count(*) FROM pg_tables WHERE schemaname='public' AND rowsecurity) AS rls_enabled,(SELECT count(*) FROM pg_policies WHERE schemaname='public') AS policy_count;
ROLLBACK;
